CREATE OR REPLACE FUNCTION public.delayed_commit(p_child uuid, p_actor uuid, p_revision bigint, p_state jsonb, p_event text, p_at bigint, p_advanced boolean, p_request uuid DEFAULT NULL::uuid, p_fingerprint jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE c private.delayed_children;m private.delayed_matches;r private.delayed_commands;now_i timestamptz;event_time timestamptz;
 done boolean;next_actor uuid;next_due bigint;expected_due timestamptz;
BEGIN
 IF p_actor IS NOT NULL THEN PERFORM private.require_account_enabled(p_actor); END IF;
 PERFORM private.delayed_words_check_health();
 PERFORM pg_advisory_xact_lock_shared(731907241);
 IF p_actor IS NOT NULL AND p_request IS NOT NULL THEN
  PERFORM pg_advisory_xact_lock(hashtextextended(p_actor::text||p_request::text,319));
 END IF;
 SELECT * INTO STRICT m FROM private.delayed_matches WHERE id=(SELECT match_id FROM private.delayed_children WHERE id=p_child) FOR UPDATE;
 SELECT * INTO STRICT c FROM private.delayed_children WHERE id=p_child FOR UPDATE;
 IF p_actor IS NOT NULL THEN
  PERFORM private.delayed_actor(p_actor);
  IF p_actor NOT IN(m.organizer,m.opponent) THEN RAISE EXCEPTION 'delayed:not_authorized' USING ERRCODE='42501';END IF;
 END IF;
 IF c.game_type NOT IN('run21','tri-towers','quintzee','boxdrop','mega-card-golf','take-two','crib-lab','chucky-showdown') OR EXISTS(SELECT FROM private.delayed_removals WHERE match_id=m.id) THEN RAISE EXCEPTION 'delayed:removed_or_unavailable';END IF;
 IF p_request IS NOT NULL THEN
  SELECT * INTO r FROM private.delayed_commands WHERE actor=p_actor AND request_id=p_request;
  IF FOUND THEN
   IF r.child_id IS DISTINCT FROM p_child OR r.fingerprint IS DISTINCT FROM p_fingerprint THEN RAISE EXCEPTION 'delayed:request_conflict'; END IF;
   RETURN jsonb_build_object('outcome','duplicate','record',private.delayed_child_record(c));
  END IF;
 END IF;
 IF c.revision IS DISTINCT FROM p_revision OR c.terminal THEN RETURN jsonb_build_object('outcome','conflict','record',private.delayed_child_record(c)); END IF;
 IF m.status<>'active' OR private.delayed_held(m.id) THEN RAISE EXCEPTION 'delayed:held';END IF;
 now_i:=clock_timestamp();event_time:=to_timestamp(p_at/1000.0);
 expected_due:=least(c.expires_at,c.gameplay_due_at);
 IF p_event='action' THEN
  IF p_actor IS DISTINCT FROM c.actor OR p_request IS NULL OR p_fingerprint IS NULL THEN RAISE EXCEPTION 'delayed:not_your_turn';END IF;
  IF now_i>=expected_due THEN RETURN jsonb_build_object('outcome','deadline','record',private.delayed_child_record(c)); END IF;
 ELSIF p_event='tick' THEN
  IF p_request IS NOT NULL OR now_i<expected_due OR abs(extract(epoch FROM expected_due)*1000-p_at)>=1 THEN RAISE EXCEPTION 'delayed:invalid_tick'; END IF;
  IF c.expires_at<=coalesce(c.gameplay_due_at,c.expires_at) THEN
   PERFORM private.delayed_expire(c.id,c.segment,c.expires_at);
   SELECT * INTO c FROM private.delayed_children WHERE id=p_child;
   RETURN jsonb_build_object('outcome','committed','record',private.delayed_child_record(c));
  END IF;
 ELSE RAISE EXCEPTION 'delayed:invalid_event';END IF;
 IF event_time>now_i OR event_time<c.available_at-interval '1 millisecond' OR p_state->>'version' IS DISTINCT FROM 'delayed/1'
  OR p_state->>'child' IS DISTINCT FROM c.id::text OR p_state->>'game' IS DISTINCT FROM c.game_type
  OR p_advanced IS NULL THEN RAISE EXCEPTION 'delayed:invalid_state';END IF;
 done:=coalesce((p_state->>'completed')::boolean,false);
 next_actor:=(p_state->'players'->>(p_state->>'turn')::integer)::uuid;
 IF next_actor IS NULL OR next_actor NOT IN(m.organizer,m.opponent) OR (NOT p_advanced AND next_actor<>c.actor) OR (done AND NOT p_advanced)
 THEN RAISE EXCEPTION 'delayed:invalid_actor';END IF;
 next_due:=CASE WHEN c.game_type IN('crib-lab','chucky-showdown') THEN (p_state#>>'{board,nextDue}')::bigint ELSE (p_state#>>'{board,deadline}')::bigint END;
 UPDATE private.delayed_children SET state=p_state,revision=revision+1,
  actor=next_actor,segment=segment+CASE WHEN p_advanced THEN 1 ELSE 0 END,
  available_at=CASE WHEN p_advanced THEN event_time ELSE available_at END,
  last_call_at=CASE WHEN p_advanced THEN event_time+interval '24 hours' ELSE last_call_at END,
  expires_at=CASE WHEN p_advanced THEN event_time+interval '36 hours' ELSE expires_at END,
  started_at=to_timestamp((p_state->>'segmentStartedAt')::bigint/1000.0),gameplay_due_at=to_timestamp(next_due/1000.0)
 WHERE id=c.id RETURNING * INTO c;
 IF done THEN
  PERFORM private.delayed_record_outcome(c.id,c.revision,CASE WHEN p_state->>'winner' IS NULL THEN 'draw' ELSE 'normal' END,
   (p_state->>'winner')::uuid,jsonb_build_object('rules',c.config,'finalState',p_state));
 ELSE
  UPDATE private.delayed_matches SET revision=revision+1 WHERE id=m.id;
  PERFORM private.delayed_notify(m.id);
 END IF;
 SELECT * INTO c FROM private.delayed_children WHERE id=p_child;
 IF p_request IS NOT NULL THEN INSERT INTO private.delayed_commands VALUES(p_actor,p_request,p_child,p_fingerprint,c.revision);END IF;
 RETURN jsonb_build_object('outcome','committed','record',private.delayed_child_record(c));
END $function$

CREATE OR REPLACE FUNCTION public.delayed_five_alive_commit(p_child uuid, p_actor uuid, p_request uuid, p_revision bigint, p_segment bigint, p_fingerprint jsonb, p_game jsonb, p_winner uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE c private.delayed_children;m private.delayed_matches;r private.delayed_commands;old_g jsonb;old_r jsonb;new_r jsonb;
 normalized jsonb;idx integer;round_i integer;next_i integer;other_i integer;n integer;done boolean;advanced boolean;at_time timestamptz;
BEGIN
 PERFORM private.require_account_enabled(p_actor);PERFORM private.delayed_actor(p_actor);
 PERFORM private.delayed_words_check_health();PERFORM pg_advisory_xact_lock_shared(731907241);
 IF p_request IS NULL OR p_fingerprint IS NULL THEN RAISE EXCEPTION 'delayed:invalid_command';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(p_actor::text||p_request::text,319));
 SELECT * INTO STRICT m FROM private.delayed_matches WHERE id=(SELECT match_id FROM private.delayed_children WHERE id=p_child) FOR UPDATE;
 SELECT * INTO STRICT c FROM private.delayed_children WHERE id=p_child FOR UPDATE;
 IF p_actor NOT IN(m.organizer,m.opponent) OR c.game_type<>'five-alive'
  OR EXISTS(SELECT FROM private.delayed_removals WHERE match_id=m.id) THEN RAISE EXCEPTION 'delayed:not_authorized' USING ERRCODE='42501';END IF;
 SELECT * INTO r FROM private.delayed_commands WHERE actor=p_actor AND request_id=p_request;
 IF FOUND THEN
  IF r.child_id IS DISTINCT FROM p_child OR r.fingerprint IS DISTINCT FROM p_fingerprint THEN RAISE EXCEPTION 'delayed:request_conflict';END IF;
  RETURN jsonb_build_object('outcome','duplicate','record',private.delayed_child_record(c));
 END IF;
 IF c.revision IS DISTINCT FROM p_revision OR c.segment IS DISTINCT FROM p_segment OR c.terminal THEN
  RETURN jsonb_build_object('outcome','conflict','record',private.delayed_child_record(c));
 END IF;
 IF m.status<>'active' OR private.delayed_held(m.id) THEN RAISE EXCEPTION 'delayed:held';END IF;
 IF c.expires_at IS NULL THEN RAISE EXCEPTION 'five_alive:missing_deadline';END IF;
 at_time:=clock_timestamp();
 IF at_time>=c.expires_at THEN
  PERFORM private.delayed_expire(c.id,c.segment,c.expires_at);
  SELECT * INTO STRICT c FROM private.delayed_children WHERE id=p_child;
  RETURN jsonb_build_object('outcome','deadline','record',private.delayed_child_record(c));
 END IF;
 old_g:=c.state->'fiveAlive';round_i:=(old_g->>'current')::integer;
 IF round_i NOT BETWEEN 0 AND 2 OR old_g->'players' IS DISTINCT FROM jsonb_build_array(m.organizer,m.opponent)
  OR (p_game->>'current') !~ '^[0-3]$' THEN RAISE EXCEPTION 'five_alive:invalid_state';END IF;
 idx:=CASE WHEN p_actor=m.organizer THEN 0 ELSE 1 END;other_i:=1-idx;
 old_r:=old_g->'rounds'->idx->round_i;new_r:=p_game->'rounds'->idx->round_i;
 IF old_r IS NULL OR new_r IS NULL OR (old_r->>'completed')::boolean IS DISTINCT FROM false
  OR jsonb_typeof(new_r->'guesses') IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'five_alive:invalid_round';END IF;
 n:=jsonb_array_length(new_r->'guesses');
 IF n NOT BETWEEN 1 AND 6 OR n<>jsonb_array_length(old_r->'guesses')+1
  OR (new_r->'guesses')-(n-1) IS DISTINCT FROM old_r->'guesses'
  OR new_r->'answer' IS DISTINCT FROM old_r->'answer' OR new_r->'difficulty' IS DISTINCT FROM old_r->'difficulty'
  OR new_r#>>ARRAY['guesses',(n-1)::text,'word'] !~ '^[A-Z]{5}$'
  OR (new_r->>'completed')::boolean IS DISTINCT FROM (n=6 OR new_r#>>ARRAY['guesses',(n-1)::text,'word']=old_r->>'answer')
 THEN RAISE EXCEPTION 'five_alive:invalid_transition';END IF;
 advanced:=(new_r->>'completed')::boolean AND (old_g->'rounds'->other_i->round_i->>'completed')::boolean;
 IF jsonb_typeof(p_game->'sharedScores') IS DISTINCT FROM 'array' OR jsonb_array_length(p_game->'sharedScores')<>2
  OR (NOT advanced AND p_game->'sharedScores' IS DISTINCT FROM old_g->'sharedScores') THEN RAISE EXCEPTION 'five_alive:invalid_scores';END IF;
 normalized:=jsonb_set(p_game,'{current}',old_g->'current');
 normalized:=jsonb_set(normalized,'{sharedScores}',old_g->'sharedScores');
 normalized:=jsonb_set(normalized,ARRAY['rounds',idx::text,round_i::text],old_r);
 IF normalized IS DISTINCT FROM old_g THEN RAISE EXCEPTION 'five_alive:invalid_transition';END IF;
 next_i:=round_i+CASE WHEN advanced THEN 1 ELSE 0 END;
 IF (p_game->>'current')::integer IS DISTINCT FROM next_i OR (next_i<3 AND p_winner IS NOT NULL)
  OR (p_winner IS NOT NULL AND p_winner NOT IN(m.organizer,m.opponent)) THEN RAISE EXCEPTION 'five_alive:invalid_outcome';END IF;
 done:=next_i=3;
 UPDATE private.delayed_children SET state=jsonb_set(state,'{fiveAlive}',p_game),revision=revision+1,
  segment=segment+CASE WHEN advanced THEN 1 ELSE 0 END,
  available_at=CASE WHEN advanced AND NOT done THEN at_time ELSE available_at END,
  last_call_at=CASE WHEN advanced AND NOT done THEN at_time+interval '24 hours' ELSE last_call_at END,
  expires_at=CASE WHEN advanced AND NOT done THEN at_time+interval '36 hours' ELSE expires_at END
 WHERE id=c.id RETURNING * INTO c;
 UPDATE private.delayed_matches SET revision=revision+1 WHERE id=m.id;
 IF done THEN
  PERFORM private.delayed_record_outcome(c.id,c.revision,CASE WHEN p_winner IS NULL THEN 'draw' ELSE 'normal' END,p_winner,
   jsonb_build_object('rules',c.config,'finalState',p_game));
 ELSE PERFORM private.delayed_notify(m.id);END IF;
 SELECT * INTO STRICT c FROM private.delayed_children WHERE id=p_child;
 INSERT INTO private.delayed_commands(actor,request_id,child_id,fingerprint,revision) VALUES(p_actor,p_request,p_child,p_fingerprint,c.revision);
 RETURN jsonb_build_object('outcome','committed','record',private.delayed_child_record(c));
END $function$

CREATE OR REPLACE FUNCTION public.delayed_respond(p_match uuid, p_request uuid, p_offer_hash text, p_action text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE actor_i uuid:=auth.uid(); m private.delayed_matches; receipt private.delayed_requests; fingerprint jsonb;
 c private.delayed_children; first_actor uuid; at_time timestamptz; response jsonb; dealt jsonb;
BEGIN
 PERFORM private.delayed_words_check_health();
 PERFORM pg_advisory_xact_lock_shared(731907241);
 PERFORM private.delayed_actor(actor_i);
 IF p_request IS NULL THEN RAISE EXCEPTION 'delayed:request_required'; END IF;
 fingerprint:=jsonb_build_object('op',p_action,'match',p_match,'hash',p_offer_hash);
 PERFORM pg_advisory_xact_lock(hashtextextended(actor_i::text||p_request::text,317));
 SELECT * INTO receipt FROM private.delayed_requests WHERE delayed_requests.actor=actor_i AND request_id=p_request;
 IF FOUND THEN IF receipt.fingerprint IS DISTINCT FROM fingerprint THEN RAISE EXCEPTION 'delayed:request_conflict'; END IF; RETURN receipt.response; END IF;
 SELECT * INTO STRICT m FROM private.delayed_matches WHERE id=p_match FOR UPDATE;
 IF p_action IS NULL OR p_action NOT IN('accept','decline','cancel') OR
  actor_i IS DISTINCT FROM (CASE WHEN p_action='cancel' THEN m.organizer ELSE m.opponent END) THEN RAISE EXCEPTION 'delayed:not_authorized' USING ERRCODE='42501'; END IF;
 IF m.status<>'invited' OR p_offer_hash IS DISTINCT FROM m.offer_hash THEN RAISE EXCEPTION 'delayed:offer_changed'; END IF;
 IF p_action='cancel' THEN
  PERFORM private.delayed_delete_pending_invitation(m.id);
  response:=jsonb_build_object('status','cancelled','deleted',true);
  INSERT INTO private.delayed_requests VALUES(actor_i,p_request,fingerprint,m.id,response);
  RETURN response;
 END IF;
 at_time:=clock_timestamp();
 IF at_time>=m.expires_at THEN UPDATE private.delayed_matches SET status='expired',revision=revision+1 WHERE id=m.id; response:='{"status":"expired"}';
 ELSIF p_action='accept' THEN
  PERFORM private.delayed_actor(m.organizer);
  IF EXISTS(SELECT FROM public.system_settings WHERE key='maintenance_mode' AND value->>'enabled'='true') THEN RAISE EXCEPTION 'delayed:maintenance'; END IF;
  IF NOT EXISTS(SELECT FROM private.delayed_release WHERE singleton AND admission_enabled) OR private.delayed_held(m.id) THEN RAISE EXCEPTION 'delayed:admission_closed'; END IF;
  IF EXISTS(SELECT FROM private.delayed_children WHERE match_id=m.id AND game_type='mega-card-golf') AND NOT ((SELECT async_enabled FROM private.mega_competition_release WHERE singleton) OR private.mega_test_async_allowed(m.organizer,m.opponent,NULL,m.id,m.real_money)) THEN RAISE EXCEPTION 'delayed:admission_closed';END IF;
 IF m.real_money AND NOT EXISTS(SELECT FROM private.delayed_release WHERE singleton AND real_qualified) THEN RAISE EXCEPTION 'delayed:real_money_closed';END IF;
  IF NOT private.delayed_multi_enabled() AND ((SELECT count(*) FROM private.delayed_children WHERE match_id=m.id)<>1 OR EXISTS(SELECT FROM private.delayed_children WHERE match_id=m.id AND game_type<>'ptown-words')) THEN RAISE EXCEPTION 'delayed:scope_closed';END IF;
  IF EXISTS(SELECT FROM private.delayed_children WHERE match_id=m.id AND game_type='take-two')
   AND NOT (SELECT enabled FROM private.delayed_take_two_release WHERE singleton) THEN RAISE EXCEPTION 'delayed:admission_closed';END IF;
  FOR c IN SELECT * FROM private.delayed_children WHERE match_id=m.id ORDER BY ordinal FOR UPDATE LOOP
   IF c.game_type NOT IN('five-alive','chess','ptown-words','run21','tri-towers','quintzee','boxdrop','mega-card-golf','take-two','crib-lab','chucky-showdown') THEN RAISE EXCEPTION 'delayed:scope_closed';END IF;
   IF c.game_type IN('crib-lab','chucky-showdown') AND NOT EXISTS(SELECT FROM private.originals_release WHERE game=c.game_type AND async_enabled AND (NOT m.real_money OR async_real_qualified)) THEN RAISE EXCEPTION 'originals:async_closed';END IF;
   dealt:=NULL;
   IF c.game_type='five-alive' THEN
    IF NOT EXISTS(SELECT FROM private.five_alive_release WHERE singleton AND async_enabled AND (NOT m.real_money OR async_real_qualified)) THEN RAISE EXCEPTION 'delayed:admission_closed';END IF;
    dealt:=private.five_alive_async_deal(c.id,m.organizer,m.opponent,c.config->>'poolVersion');
   END IF;
   IF c.game_type='ptown-words' THEN dealt:=private.ptown_words_deal(jsonb_build_object('rules',c.config,'players',(SELECT jsonb_agg(jsonb_build_object('id',p.id,'userId',p.id,'name',p.username,'seat',CASE WHEN p.id=m.organizer THEN 1 ELSE 2 END,'isBot',false) ORDER BY CASE WHEN p.id=m.organizer THEN 1 ELSE 2 END) FROM public.profiles p WHERE p.id IN(m.organizer,m.opponent))),floor(extract(epoch FROM at_time)*1000)::bigint);
   first_actor:=(dealt->'players'->(dealt->>'turnIndex')::int->>'id')::uuid;
   ELSE first_actor:=CASE WHEN get_byte(extensions.gen_random_bytes(1),0)%2=0 THEN m.organizer ELSE m.opponent END;END IF;
   IF c.game_type='take-two' THEN
    INSERT INTO private.delayed_take_two_deals(child_id,round,deck)
    SELECT c.id,r,private.take_two_shuffle() FROM generate_series(1,3) r;
   END IF;
   IF c.game_type='chess' THEN
    IF NOT private.chess_actor_allowed(m.organizer) OR NOT private.chess_actor_allowed(m.opponent) OR NOT EXISTS(SELECT FROM private.chess_release WHERE singleton AND enabled AND admission_enabled AND async_enabled AND (NOT m.real_money OR real_qualified)) THEN RAISE EXCEPTION 'chess:async_closed';END IF;
    dealt:=private.chess_seed(jsonb_build_object('identity',jsonb_build_object('sessionId',m.id,'dealerGameId',c.id,'roundId',c.id),'players',(SELECT jsonb_agg(jsonb_build_object('id',p.id,'userId',p.id,'name',p.username,'seat',CASE WHEN p.id=first_actor THEN 1 ELSE 2 END,'isBot',false) ORDER BY CASE WHEN p.id=first_actor THEN 1 ELSE 2 END) FROM public.profiles p WHERE p.id IN(m.organizer,m.opponent))),'async',floor(extract(epoch FROM at_time)*1000)::bigint);
   END IF;
   UPDATE private.delayed_children SET state=dealt,starter=first_actor,actor=first_actor,segment=1,revision=1,
    available_at=at_time,last_call_at=at_time+interval '24 hours',expires_at=at_time+interval '36 hours' WHERE id=c.id;
  END LOOP;
  UPDATE private.delayed_matches SET status='active',accepted_at=at_time,revision=revision+1 WHERE id=m.id;
  response:='{"status":"active"}';
 ELSE
  UPDATE private.delayed_matches SET status=CASE p_action WHEN 'decline' THEN 'declined' ELSE 'cancelled' END,revision=revision+1 WHERE id=m.id;
  response:=jsonb_build_object('status',CASE p_action WHEN 'decline' THEN 'declined' ELSE 'cancelled' END);
 END IF;
 INSERT INTO private.delayed_requests VALUES(actor_i,p_request,fingerprint,m.id,response);
 PERFORM private.delayed_notify(m.id); RETURN response;
END $function$

CREATE OR REPLACE FUNCTION private.five_alive_async_expire(c private.delayed_children, m private.delayed_matches, p_segment bigint, p_expiry timestamp with time zone)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE game jsonb:=c.state->'fiveAlive';round_i integer;first_done boolean;second_done boolean;winner uuid;reason_i text;
BEGIN
 IF m.status<>'active' OR c.terminal OR private.delayed_held(m.id) OR c.segment<>p_segment
  OR c.expires_at IS DISTINCT FROM p_expiry OR c.expires_at IS NULL OR clock_timestamp()<c.expires_at THEN RETURN false;END IF;
 round_i:=(game->>'current')::integer;
 IF round_i NOT BETWEEN 0 AND 2 THEN RAISE EXCEPTION 'five_alive:invalid_round';END IF;
 first_done:=(game->'rounds'->0->round_i->>'completed')::boolean;
 second_done:=(game->'rounds'->1->round_i->>'completed')::boolean;
 IF first_done IS NULL OR second_done IS NULL OR first_done AND second_done THEN RAISE EXCEPTION 'five_alive:invalid_round';END IF;
 IF NOT first_done AND NOT second_done THEN reason_i:='draw';winner:=NULL;
 ELSE reason_i:='timeout_forfeit';winner:=CASE WHEN first_done THEN m.organizer ELSE m.opponent END;END IF;
 PERFORM private.delayed_record_outcome(c.id,c.revision,reason_i,winner,
  jsonb_build_object('round',round_i+1,'segment',c.segment,'expiredAt',c.expires_at,'bothExpired',NOT first_done AND NOT second_done));
 RETURN true;
END $function$

CREATE OR REPLACE FUNCTION private.delayed_finalize(parent uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE financial_id uuid; m private.delayed_matches; receipt private.delayed_settlements; n integer; completed integer;
 net_i bigint; hash text; a uuid:=gen_random_uuid(); b uuid:=gen_random_uuid(); dg uuid:=gen_random_uuid(); result_id uuid:=gen_random_uuid(); changes jsonb;
BEGIN
 PERFORM pg_advisory_xact_lock_shared(731907241);
 SELECT * INTO STRICT m FROM private.delayed_matches WHERE id=parent FOR UPDATE;
 SELECT coalesce((SELECT financial_game_id FROM private.delayed_current_corrections WHERE match_id=parent),parent) INTO financial_id;
 SELECT * INTO receipt FROM private.delayed_current_settlements WHERE match_id=parent;
 IF FOUND THEN RETURN to_jsonb(receipt); END IF;
 IF m.status<>'active' OR private.delayed_held(parent) THEN RAISE EXCEPTION 'delayed:not_settleable'; END IF;
 SELECT count(*) INTO n FROM private.delayed_children WHERE match_id=parent;
 SELECT count(*),coalesce(sum(o.organizer_delta),0),md5(coalesce(jsonb_agg(to_jsonb(o) ORDER BY c.ordinal)::text,''))
  INTO completed,net_i,hash FROM private.delayed_children c JOIN private.delayed_current_outcomes o ON o.child_id=c.id AND o.match_id=c.match_id
  WHERE c.match_id=parent AND c.terminal;
 IF n=0 OR n<>jsonb_array_length(m.offer) OR completed<>n THEN RETURN NULL; END IF;
 IF abs(net_i)>2147483647 THEN RAISE EXCEPTION 'delayed:amount_overflow'; END IF;
 INSERT INTO public.games(id,name,game_type,status,current_host,real_money,pot,buy_in)
  VALUES(financial_id,'Delayed Head-to-Head','delayed-head-to-head','game_over',m.organizer,m.real_money,0,0);
 INSERT INTO public.dealer_games(id,session_id,dealer_user_id,game_type,config)
  VALUES(dg,financial_id,m.organizer,'delayed-head-to-head',jsonb_build_object('offerHash',m.offer_hash,'policy',m.policy_version));
 UPDATE public.games SET current_game_uuid=dg WHERE id=financial_id;
 INSERT INTO public.players(id,game_id,user_id,position,chips,status,is_bot,sitting_out,waiting)
  VALUES(a,financial_id,m.organizer,1,0,'active',false,false,false),(b,financial_id,m.opponent,2,0,'active',false,false,false);
 changes:=jsonb_build_object(a::text,net_i,b::text,-net_i);
 INSERT INTO public.game_results(id,game_id,dealer_game_id,hand_number,settlement_key,game_type,
  winner_player_id,winner_username,winning_hand_description,pot_won,player_chip_changes,is_chopped)
 VALUES(result_id,financial_id,dg,1,'delayed_parent','delayed-head-to-head',CASE WHEN net_i>0 THEN a WHEN net_i<0 THEN b END,
  CASE WHEN net_i=0 THEN 'Tie' ELSE (SELECT username FROM public.profiles WHERE id=CASE WHEN net_i>0 THEN m.organizer ELSE m.opponent END) END,
  'Delayed match aggregate',abs(net_i)::integer,changes,net_i=0);
 IF net_i<>0 THEN
  PERFORM public.settle_gameplay_chip_transfers(financial_id,jsonb_build_array(jsonb_build_object(
   'from',jsonb_build_object('kind','player','playerId',CASE WHEN net_i>0 THEN b ELSE a END),
   'to',jsonb_build_object('kind','player','playerId',CASE WHEN net_i>0 THEN a ELSE b END),'amount',abs(net_i)::integer)),'win');
 END IF;
 INSERT INTO public.session_player_snapshots(game_id,dealer_game_id,hand_number,player_id,user_id,username,chips,is_bot)
 SELECT financial_id,dg,1,p.id,p.user_id,pr.username,p.chips,false FROM public.players p JOIN public.profiles pr ON pr.id=p.user_id WHERE p.game_id=financial_id;
 -- record_session_results owns account posting from these final snapshots.
 UPDATE public.games SET status='session_ended',session_ended_at=clock_timestamp(),game_over_at=clock_timestamp(),pending_session_end=false WHERE id=financial_id;
 IF m.real_money AND ((SELECT count(*) FROM public.player_transactions WHERE source_game_id=financial_id AND transaction_type='SessionResult')<>2
  OR NOT EXISTS(SELECT FROM public.player_transactions WHERE source_game_id=financial_id AND profile_id=m.organizer AND transaction_type='SessionResult' AND player_transactions.amount=net_i)
  OR NOT EXISTS(SELECT FROM public.player_transactions WHERE source_game_id=financial_id AND profile_id=m.opponent AND transaction_type='SessionResult' AND player_transactions.amount=-net_i))
 THEN RAISE EXCEPTION 'delayed:account_posting_mismatch'; END IF;
 IF financial_id<>parent THEN
 INSERT INTO private.delayed_reopened_settlements(match_id,game_id,dealer_game_id,result_id,outcome_hash,child_count,organizer_delta,opponent_delta,generation)
 VALUES(parent,financial_id,dg,result_id,hash,n,net_i,-net_i,(SELECT generation FROM private.delayed_current_corrections WHERE match_id=parent)) RETURNING match_id,game_id,dealer_game_id,private.delayed_reopened_settlements.result_id,outcome_hash,child_count,organizer_delta,opponent_delta,created_at INTO receipt;
 ELSE
 INSERT INTO private.delayed_settlements(match_id,game_id,dealer_game_id,result_id,outcome_hash,child_count,organizer_delta,opponent_delta)
 VALUES(parent,financial_id,dg,result_id,hash,n,net_i,-net_i) RETURNING * INTO receipt;
 END IF;
 UPDATE private.delayed_matches SET status='settled',settled_at=clock_timestamp(),revision=revision+1 WHERE id=parent;
 PERFORM private.delayed_notify(parent);
 RETURN to_jsonb(receipt);
END $function$

CREATE OR REPLACE FUNCTION private.delayed_record_outcome(child uuid, expected_revision bigint, reason_i text, winner_i uuid, evidence_i jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE c private.delayed_children; m private.delayed_matches; old private.delayed_outcomes; delta_i integer;
BEGIN
 PERFORM pg_advisory_xact_lock_shared(731907241);
 SELECT * INTO STRICT m FROM private.delayed_matches WHERE id=(SELECT match_id FROM private.delayed_children WHERE id=child) FOR UPDATE;
 SELECT * INTO STRICT c FROM private.delayed_children WHERE id=child FOR UPDATE;
 SELECT * INTO old FROM private.delayed_current_outcomes WHERE child_id=child;
 IF FOUND THEN
  IF (old.terminal_revision,old.reason,old.winner,old.evidence) IS DISTINCT FROM (expected_revision,reason_i,winner_i,evidence_i)
  THEN RAISE EXCEPTION 'delayed:outcome_conflict'; END IF;
  RETURN to_jsonb(old);
 END IF;
 IF m.status<>'active' OR c.terminal OR c.revision IS DISTINCT FROM expected_revision OR private.delayed_held(m.id)
 THEN RAISE EXCEPTION 'delayed:stale_outcome'; END IF;
 IF reason_i IS NULL OR reason_i NOT IN('normal','timeout_forfeit','draw','void') OR evidence_i IS NULL
 OR (reason_i IN('normal','timeout_forfeit') AND (winner_i IS NULL OR winner_i NOT IN(m.organizer,m.opponent)))
 OR (reason_i IN('draw','void') AND winner_i IS NOT NULL) THEN RAISE EXCEPTION 'delayed:invalid_outcome'; END IF;
 delta_i:=CASE WHEN winner_i=m.organizer THEN c.stake WHEN winner_i=m.opponent THEN -c.stake ELSE 0 END;
 IF EXISTS(SELECT FROM private.delayed_current_corrections WHERE child_id=child) THEN
 INSERT INTO private.delayed_reopened_outcomes(child_id,match_id,terminal_revision,segment,reason,winner,organizer_delta,opponent_delta,evidence,generation)
 VALUES(c.id,m.id,c.revision,c.segment,reason_i,winner_i,delta_i,-delta_i,evidence_i,(SELECT generation FROM private.delayed_current_corrections WHERE child_id=child)) RETURNING child_id,match_id,terminal_revision,segment,reason,winner,organizer_delta,opponent_delta,evidence,completed_at INTO old;
 ELSE
 INSERT INTO private.delayed_outcomes(child_id,match_id,terminal_revision,segment,reason,winner,organizer_delta,opponent_delta,evidence)
 VALUES(c.id,m.id,c.revision,c.segment,reason_i,winner_i,delta_i,-delta_i,evidence_i) RETURNING * INTO old;
 END IF;
 UPDATE private.delayed_children SET terminal=true,revision=revision+1 WHERE id=c.id;
 UPDATE private.delayed_matches SET revision=revision+1 WHERE id=m.id;
 PERFORM private.delayed_finalize(m.id);
 PERFORM private.delayed_notify(m.id);
 RETURN to_jsonb(old);
END $function$

CREATE OR REPLACE FUNCTION private.delayed_notify_before_reviews(parent uuid)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE m private.delayed_matches; recipient uuid; n integer; earliest timestamptz; urgent boolean; p jsonb; k text; action boolean;
BEGIN
 SELECT * INTO STRICT m FROM private.delayed_matches WHERE id=parent;
 IF EXISTS(SELECT FROM private.delayed_removals WHERE match_id=m.id) THEN RETURN;END IF; FOREACH recipient IN ARRAY ARRAY[m.organizer,m.opponent] LOOP
  SELECT count(*),min(expires_at),coalesce(bool_or(last_call_at<=clock_timestamp()),false)
   INTO n,earliest,urgent FROM private.delayed_children WHERE match_id=m.id AND NOT terminal AND private.five_alive_or_actor(delayed_children,recipient);
  FOREACH k IN ARRAY ARRAY['invitation','turn','invitation_closed'] LOOP
   action:=CASE k WHEN 'invitation' THEN m.status='invited' AND recipient=m.opponent AND clock_timestamp()<m.expires_at
    WHEN 'turn' THEN m.status='active' AND n>0 AND NOT private.delayed_held(m.id) ELSE false END;
   IF k='settled' AND m.status<>'settled' OR k='invitation_closed' AND m.status NOT IN('declined','cancelled','expired') THEN CONTINUE; END IF;
   p:=jsonb_build_object('status',m.status,'opponentId',CASE WHEN recipient=m.organizer THEN m.opponent ELSE m.organizer END,
    'availableCount',CASE WHEN k='turn' AND action THEN n ELSE 0 END,'earliestDeadline',CASE WHEN k='turn' AND action THEN earliest END,
    'lastCall',k='turn' AND action AND urgent,'held',private.delayed_held(m.id));
   INSERT INTO public.platform_notifications(user_id,match_id,kind,actionable,payload)
    VALUES(recipient,m.id,k,action,p)
    ON CONFLICT(user_id,match_id,kind) DO UPDATE SET actionable=EXCLUDED.actionable,payload=EXCLUDED.payload,
     revision=platform_notifications.revision+1,updated_at=clock_timestamp()
    WHERE (platform_notifications.actionable,platform_notifications.payload) IS DISTINCT FROM (EXCLUDED.actionable,EXCLUDED.payload);
  END LOOP;
 END LOOP;
END $function$

CREATE OR REPLACE FUNCTION private.delayed_notify(parent uuid)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE m private.delayed_matches;who uuid;n int;available int;k text;active boolean;p jsonb;seen boolean;
BEGIN
 PERFORM private.delayed_notify_before_reviews(parent);
 SELECT * INTO STRICT m FROM private.delayed_matches WHERE id=parent;
 IF EXISTS(SELECT FROM private.delayed_removals WHERE match_id=parent) THEN RETURN;END IF;
 IF EXISTS(SELECT FROM private.delayed_children WHERE match_id=parent AND private.five_alive_or_actor(delayed_children,m.organizer) AND NOT terminal) THEN
  INSERT INTO private.delayed_acceptance_retired VALUES(parent) ON CONFLICT DO NOTHING;
 END IF;
 FOREACH who IN ARRAY ARRAY[m.organizer,m.opponent] LOOP
  SELECT count(*) INTO available FROM private.delayed_children WHERE match_id=parent AND private.five_alive_or_actor(delayed_children,who) AND NOT terminal;
  SELECT count(*) INTO n FROM private.delayed_current_review_events e WHERE e.match_id=parent AND kind='child' AND NOT EXISTS(SELECT FROM private.delayed_review_seen s WHERE s.event_id=e.id AND s.viewer=who);
  FOREACH k IN ARRAY ARRAY['accepted','results','settled'] LOOP
   active:=CASE k WHEN 'accepted' THEN who=m.organizer AND m.status='active' AND available=0 AND NOT EXISTS(SELECT FROM private.delayed_acceptance_retired WHERE match_id=parent)
    WHEN 'results' THEN m.status='active' AND n>0
    ELSE m.status='settled' AND NOT EXISTS(SELECT FROM private.delayed_current_finale_seen WHERE match_id=parent AND viewer=who) END;
   p:=jsonb_build_object('status',m.status,'opponentId',CASE WHEN who=m.organizer THEN m.opponent ELSE m.organizer END,
    'opponentName',(SELECT username FROM public.profiles WHERE id=CASE WHEN who=m.organizer THEN m.opponent ELSE m.organizer END),'completionCount',n,'availableCount',available);
   INSERT INTO public.platform_notifications(user_id,match_id,kind,actionable,payload) VALUES(who,parent,k,active,p)
   ON CONFLICT(user_id,match_id,kind) DO UPDATE SET actionable=EXCLUDED.actionable,payload=EXCLUDED.payload,revision=platform_notifications.revision+1,updated_at=clock_timestamp()
    WHERE (platform_notifications.actionable,platform_notifications.payload) IS DISTINCT FROM (EXCLUDED.actionable,EXCLUDED.payload);
  END LOOP;
 END LOOP;
END $function$

CREATE OR REPLACE FUNCTION private.chess_sync(mode_i text, id_i uuid)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE m private.chess_matches;c private.delayed_children;parent private.delayed_matches;at_ms bigint:=floor(extract(epoch FROM clock_timestamp())*1000);s jsonb;winner uuid;
BEGIN
 IF mode_i='live' THEN
  SELECT * INTO STRICT m FROM private.chess_matches WHERE dealer_game_id=id_i;
  PERFORM 1 FROM public.rounds WHERE id=m.round_id FOR UPDATE;
  PERFORM 1 FROM public.games WHERE id=m.game_id FOR UPDATE;
  SELECT * INTO STRICT m FROM private.chess_matches WHERE dealer_game_id=id_i FOR UPDATE;
  IF m.finished OR m.paused_at IS NOT NULL THEN RETURN;END IF;
  IF m.settlement IS NOT NULL THEN PERFORM private.chess_finish_postgame(id_i);RETURN;END IF;
  IF (m.state->>'deadline')::bigint<=at_ms THEN
   UPDATE private.chess_matches SET state=private.chess_timeout_state(state),revision=revision+1 WHERE dealer_game_id=id_i;
   PERFORM private.chess_settle(id_i);
  END IF;
 ELSE
  SELECT * INTO STRICT parent FROM private.delayed_matches WHERE id=(SELECT match_id FROM private.delayed_children WHERE id=id_i AND game_type='chess') FOR UPDATE;
  SELECT * INTO STRICT c FROM private.delayed_children WHERE id=id_i FOR UPDATE;
  IF c.terminal OR parent.status<>'active' OR private.delayed_held(parent.id) THEN RETURN;END IF;
  IF (c.state->>'deadline')::bigint<=at_ms THEN
   s:=private.chess_timeout_state(c.state);winner:=(s->'winnerIds'->>0)::uuid;
   UPDATE private.delayed_children SET state=s,revision=revision+1 WHERE id=id_i RETURNING * INTO c;
   PERFORM private.delayed_record_outcome(c.id,c.revision,'timeout_forfeit',winner,jsonb_build_object('game','chess','reason','timeout','fen',s->>'fen'));
  END IF;
 END IF;
END $function$

CREATE OR REPLACE FUNCTION private.delayed_words_finish_turn(c private.delayed_children, s jsonb, at_time timestamp with time zone)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE winner uuid;
BEGIN
 UPDATE private.delayed_children SET state=s,revision=revision+1,
  actor=(s->'players'->(s->>'turnIndex')::int->>'id')::uuid,segment=segment+1,
  available_at=at_time,last_call_at=at_time+interval '24 hours',expires_at=at_time+interval '36 hours',
  started_at=NULL,gameplay_due_at=NULL WHERE id=c.id RETURNING * INTO c;
 UPDATE private.delayed_matches SET revision=revision+1 WHERE id=c.match_id;
 IF s->>'phase'='complete' THEN
  winner:=CASE WHEN jsonb_array_length(s->'winnerIds')=1 THEN (s->'winnerIds'->>0)::uuid END;
  PERFORM private.delayed_record_outcome(c.id,c.revision,CASE WHEN winner IS NULL THEN 'draw' ELSE 'normal' END,winner,
   jsonb_build_object('rules',c.config,'finalState',s,'endReason',s->>'endReason'));
 ELSE PERFORM private.delayed_notify(c.match_id); END IF;
END $function$

CREATE OR REPLACE FUNCTION private.delayed_expire(child uuid, expected_segment bigint, expected_expiry timestamp with time zone)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE c private.delayed_children; m private.delayed_matches;
BEGIN
 PERFORM pg_advisory_xact_lock_shared(731907241);
 SELECT * INTO STRICT m FROM private.delayed_matches WHERE id=(SELECT match_id FROM private.delayed_children WHERE id=child) FOR UPDATE;
 SELECT * INTO STRICT c FROM private.delayed_children WHERE id=child FOR UPDATE;
 IF c.game_type='five-alive' THEN RETURN private.five_alive_async_expire(c,m,expected_segment,expected_expiry); END IF;
 -- An entered live-rules Words turn is governed solely by its playable deadline.
 IF c.game_type='ptown-words' AND c.config->>'version' IN ('ptown-words/2','ptown-words/4') AND c.gameplay_due_at IS NOT NULL THEN
  IF m.status<>'active' OR c.terminal OR private.delayed_held(m.id) OR c.segment<>expected_segment
     OR c.expires_at IS DISTINCT FROM expected_expiry OR clock_timestamp()<c.gameplay_due_at THEN RETURN false; END IF;
  PERFORM private.delayed_words_finish_turn(c,private.ptown_words_reduce(c.state,'tick',NULL,(c.state->>'deadline')::bigint),clock_timestamp());
  RETURN true;
 END IF;
 IF m.status<>'active' OR c.terminal OR private.delayed_held(m.id) OR c.segment<>expected_segment OR c.expires_at IS DISTINCT FROM expected_expiry
  OR c.expires_at IS NULL OR clock_timestamp()<c.expires_at THEN RETURN false; END IF;
 -- An earlier active-game deadline must be resolved by the game adapter first.
 IF c.gameplay_due_at IS NOT NULL AND c.gameplay_due_at<c.expires_at THEN RETURN false; END IF;
 PERFORM private.delayed_record_outcome(c.id,c.revision,'timeout_forfeit',CASE WHEN c.actor=m.organizer THEN m.opponent ELSE m.organizer END,
  jsonb_build_object('segment',c.segment,'expiredAt',c.expires_at,'actor',c.actor));
 RETURN true;
END $function$

CREATE OR REPLACE FUNCTION public.delayed_board_action(p_child uuid, p_actor uuid, p_game text, p_request uuid, p_revision bigint, p_segment bigint, p_intent jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
 r jsonb; s jsonb; board jsonb; reduced jsonb; committed jsonb; visible jsonb;
 saved jsonb; own_boards jsonb:='[]'; items integer[]; action text:=p_intent->>'type';
 fingerprint jsonb:=jsonb_build_object('child',p_child,'revision',p_revision,'segment',p_segment,'intent',p_intent);
 at_ms bigint;
BEGIN
 IF p_actor IS NULL OR p_request IS NULL OR p_revision IS NULL OR p_segment IS NULL
    OR p_game IS NULL OR p_game NOT IN('take-two','quintzee','boxdrop') THEN RAISE EXCEPTION 'delayed:invalid_request'; END IF;
 PERFORM pg_advisory_xact_lock_shared(731907241);
 PERFORM pg_advisory_xact_lock(hashtextextended(p_actor::text||p_request::text,319));
 r:=public.delayed_load(p_child,p_actor,p_request);
 IF r->>'game_type' IS DISTINCT FROM p_game THEN RAISE EXCEPTION 'delayed:wrong_game'; END IF;
 s:=r->'state'; board:=s->'board'; at_ms:=(r->>'server_at')::bigint;
 IF nullif(r->'receipt','null') IS NOT NULL OR (r->>'held')::boolean OR (r->>'terminal')::boolean
    OR r->>'actor' IS DISTINCT FROM p_actor::text OR (r->>'revision')::bigint<>p_revision OR (r->>'segment')::bigint<>p_segment
    OR nullif(board,'null') IS NULL OR least((board->>'deadline')::bigint,floor(extract(epoch FROM (r->>'expires_at')::timestamptz)*1000)::bigint)<=at_ms
 THEN RETURN jsonb_build_object('fallback',true); END IF;
 IF s->>'child' IS DISTINCT FROM p_child::text OR s->>'game' IS DISTINCT FROM p_game
    OR s->'players'->>((s->>'turn')::integer) IS DISTINCT FROM p_actor::text OR (s->>'completed')::boolean THEN RAISE EXCEPTION 'delayed:identity'; END IF;
 IF action IS NULL OR NOT (CASE p_game WHEN 'take-two' THEN action IN('pair','draw','take_score')
  WHEN 'quintzee' THEN action IN('roll','score','score_zero') ELSE action IN('place','recycle','take_score') END)
 THEN RAISE EXCEPTION 'delayed:invalid_action'; END IF;
 IF p_intent ? 'items' THEN
  IF jsonb_typeof(p_intent->'items')<>'array' OR jsonb_array_length(p_intent->'items')>5 THEN RAISE EXCEPTION 'delayed:invalid_items';END IF;
  IF EXISTS(SELECT FROM jsonb_array_elements(p_intent->'items') i WHERE jsonb_typeof(i)<>'number' OR i::text !~ '^-?[0-9]+$'
    OR i::text::numeric NOT BETWEEN (CASE WHEN action='pair' THEN -1 ELSE 0 END) AND (CASE WHEN action='pair' THEN 32 ELSE 2147483647 END)) THEN RAISE EXCEPTION 'delayed:invalid_items'; END IF;
  items:=ARRAY(SELECT value::integer FROM jsonb_array_elements_text(p_intent->'items') WITH ORDINALITY ORDER BY ordinality);
 ELSIF action IN('pair','roll','score','score_zero','place','recycle') THEN RAISE EXCEPTION 'delayed:invalid_items'; END IF;
 IF action='pair' AND (cardinality(items)<>2 OR items[1]=items[2]) THEN RAISE EXCEPTION 'delayed:invalid_items'; END IF;
 IF p_game='take-two' THEN
  reduced:=public.delayed_take_two_core(p_child,'reduce',(s->>'round')::int,(s->'totals'->>p_actor::text)::bigint,board,action,items,at_ms);
 ELSE
  reduced:=public.delayed_board_core(p_game,'reduce',r->'config',(s->'totals'->>p_actor::text)::bigint,board,action,items,at_ms);
 END IF;
 -- Reuse this exact roll/deal at a stage boundary. The existing adapter owns
 -- advancement, bonuses, authoritative settlement and revision conflict recovery.
 IF reduced->>'phase'='stage_complete' THEN RETURN jsonb_build_object('boundary',r,'reduced',reduced); END IF;
 committed:=public.delayed_commit(p_child,p_actor,p_revision,jsonb_set(s,'{board}',reduced),'action',at_ms,false,p_request,fingerprint);
 IF committed->>'outcome'<>'committed' THEN RETURN jsonb_build_object('fallback',true); END IF;
 r:=(committed->'record')||jsonb_build_object('reviewed',r->'reviewed');
 IF p_game='take-two' THEN visible:=public.delayed_take_two_core(p_child,'visible',p_board=>reduced);
 ELSE visible:=public.delayed_board_core(p_game,'visible',p_board=>reduced); END IF;
 FOR saved IN SELECT value->'board' FROM jsonb_array_elements(s->'attempts') WHERE value->>'actor'=p_actor::text LOOP
  own_boards:=own_boards||jsonb_build_array(CASE WHEN p_game='take-two' THEN public.delayed_take_two_core(p_child,'visible',p_board=>saved)
   ELSE public.delayed_board_core(p_game,'visible',p_board=>saved) END);
 END LOOP;
 RETURN jsonb_build_object('record',r,'visible',visible,'ownBoards',own_boards);
END $function$

CREATE OR REPLACE FUNCTION public.admin_correct_chess_timeout(p_request uuid, p_child uuid, p_expected_revision bigint, p_outcome_hash text, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE c private.delayed_children;m private.delayed_matches;o private.delayed_outcomes;s private.delayed_settlements;
 prior private.delayed_corrections;fp jsonb;restored private.delayed_children;at_i timestamptz:=clock_timestamp();at_ms bigint;
 opening bigint;last_move bigint;bank jsonb;actor_i uuid:=auth.uid();pa public.players;pb public.players;
 ta public.player_transactions;tb public.player_transactions;ra jsonb;rb jsonb;generation_i integer;financial_id uuid:=gen_random_uuid();
BEGIN
 IF actor_i IS NULL OR NOT public.has_role(actor_i,'admin'::public.app_role) THEN RAISE EXCEPTION 'chess_correction:not_authorized' USING ERRCODE='42501';END IF;
 IF p_request IS NULL OR p_child IS NULL OR p_expected_revision IS NULL OR p_outcome_hash IS NULL OR length(trim(coalesce(p_reason,''))) NOT BETWEEN 12 AND 2000 THEN RAISE EXCEPTION 'chess_correction:identity_and_reason_required';END IF;
 fp:=jsonb_build_object('child',p_child,'revision',p_expected_revision,'outcomeHash',p_outcome_hash,'reason',p_reason);
 PERFORM pg_advisory_xact_lock(731907241);
 SELECT * INTO prior FROM private.delayed_corrections WHERE id=p_request;
 IF FOUND THEN
  IF prior.actor IS DISTINCT FROM actor_i OR prior.fingerprint IS DISTINCT FROM fp THEN RAISE EXCEPTION 'chess_correction:request_conflict';END IF;
  RETURN jsonb_build_object('id',prior.id,'matchId',prior.match_id,'childId',prior.child_id,'reversalIds',prior.reversal_ids,'outcome','already_corrected');
 END IF;
 SELECT * INTO STRICT m FROM private.delayed_matches WHERE id=(SELECT match_id FROM private.delayed_children WHERE id=p_child) FOR UPDATE;
 SELECT * INTO STRICT c FROM private.delayed_children WHERE id=p_child FOR UPDATE;
 SELECT coalesce(max(generation),0)+1 INTO generation_i FROM private.delayed_corrections WHERE match_id=m.id;
 SELECT * INTO STRICT o FROM private.delayed_current_outcomes WHERE child_id=c.id;
 SELECT * INTO STRICT s FROM private.delayed_current_settlements WHERE match_id=m.id;
 IF private.delayed_held(m.id) OR m.status<>'settled' OR NOT m.real_money OR NOT c.terminal OR c.game_type<>'chess' OR c.revision<>p_expected_revision
 OR s.outcome_hash<>p_outcome_hash OR s.child_count<>1 OR (SELECT count(*) FROM private.delayed_children WHERE match_id=m.id)<>1
 OR o.reason<>'timeout_forfeit' OR c.state->>'reason'<>'timeout' OR c.state->>'phase'<>'complete'
 OR c.state#>>'{rules,version}'<>'ptown-chess/1' OR c.state#>>'{rules,turnMs}'<>'300000'
 OR o.organizer_delta<>s.organizer_delta OR abs(s.organizer_delta)<>c.stake
 OR c.actor::text IS DISTINCT FROM c.state->'players'->(c.state->>'turnIndex')::int->>'id'
 OR c.state->>'fen' IS DISTINCT FROM coalesce(c.state#>>'{moves,-1,fen}',c.state->>'initialFen')
 OR EXISTS(SELECT FROM private.delayed_removals WHERE match_id=m.id)
 THEN RAISE EXCEPTION 'chess_correction:evidence_mismatch';END IF;
 SELECT max((fingerprint->>'revision')::bigint) INTO last_move FROM private.chess_requests WHERE mode='async' AND match_id=c.id AND fingerprint#>>'{intent,type}'='move';
 SELECT min((fingerprint->>'revision')::bigint) INTO opening FROM private.chess_requests WHERE mode='async' AND match_id=c.id AND actor=c.actor
 AND fingerprint#>>'{intent,type}'='open' AND (fingerprint->>'revision')::bigint>coalesce(last_move,-1);
 IF opening IS NULL OR c.state->>'opened'<>'true' THEN RAISE EXCEPTION 'chess_correction:turn_receipt_missing';END IF;
 SELECT coalesce(jsonb_agg(slot ORDER BY slot),'[]') INTO bank FROM jsonb_array_elements(c.state->'banks'->c.actor::text) slot
 WHERE NOT EXISTS(SELECT FROM private.chess_requests r WHERE r.mode='async' AND r.match_id=c.id AND r.actor=c.actor
 AND (r.fingerprint->>'revision')::bigint>=opening AND r.fingerprint#>>'{intent,type}'='bank' AND r.fingerprint#>'{intent,slot}'=slot);
 SELECT * INTO STRICT pa FROM public.players WHERE game_id=s.game_id AND user_id=m.organizer AND NOT is_bot FOR UPDATE;
 SELECT * INTO STRICT pb FROM public.players WHERE game_id=s.game_id AND user_id=m.opponent AND NOT is_bot FOR UPDATE;
 SELECT * INTO STRICT ta FROM public.player_transactions WHERE source_game_id=s.game_id AND profile_id=m.organizer AND transaction_type='SessionResult' FOR UPDATE;
 SELECT * INTO STRICT tb FROM public.player_transactions WHERE source_game_id=s.game_id AND profile_id=m.opponent AND transaction_type='SessionResult' FOR UPDATE;
 IF pa.chips<>s.organizer_delta OR pb.chips<>s.opponent_delta OR ta.amount<>s.organizer_delta OR tb.amount<>s.opponent_delta
 OR EXISTS(SELECT FROM public.player_transactions WHERE reversal_of IN(ta.id,tb.id)) THEN RAISE EXCEPTION 'chess_correction:financial_evidence_mismatch';END IF;
 ra:=public.admin_reverse_account_entry(gen_random_uuid(),ta.id,p_reason);
 rb:=public.admin_reverse_account_entry(gen_random_uuid(),tb.id,p_reason);
 PERFORM public.settle_gameplay_chip_transfers(s.game_id,jsonb_build_array(jsonb_build_object(
 'from',jsonb_build_object('kind','player','playerId',CASE WHEN s.organizer_delta>0 THEN pa.id ELSE pb.id END),
 'to',jsonb_build_object('kind','player','playerId',CASE WHEN s.organizer_delta>0 THEN pb.id ELSE pa.id END),
 'amount',abs(s.organizer_delta))),'transfer');
 IF EXISTS(SELECT FROM public.players WHERE id IN(pa.id,pb.id) AND chips<>0) THEN RAISE EXCEPTION 'chess_correction:unbalanced_reversal';END IF;
 at_ms:=floor(extract(epoch FROM at_i)*1000);
 restored:=c;
 restored.state:=(c.state-ARRAY['reason','terminal','movePresentation'])||jsonb_build_object('phase','playing','winnerIds','[]'::jsonb,
 'scores',jsonb_build_object(m.organizer::text,0,m.opponent::text,0),'deadline',at_ms+129600000,'clockDuration',300000,'opened',false,
 'banks',jsonb_set(c.state->'banks',ARRAY[c.actor::text],bank));
 restored.terminal:=false;restored.revision:=c.revision+1;restored.segment:=c.segment+1;
 restored.available_at:=at_i;restored.last_call_at:=at_i+interval '24 hours';restored.expires_at:=at_i+interval '36 hours';
 restored.started_at:=NULL;restored.gameplay_due_at:=NULL;
 INSERT INTO private.delayed_corrections(id,child_id,match_id,actor,reason,fingerprint,before_child,restored_child,before_parent,original_outcome,original_settlement,reversal_ids,financial_game_id,transaction_id,executor_role,created_at,generation)
 VALUES(p_request,c.id,m.id,actor_i,p_reason,fp,to_jsonb(c),to_jsonb(restored),to_jsonb(m),to_jsonb(o),to_jsonb(s),ARRAY[(ra->>'id')::uuid,(rb->>'id')::uuid],financial_id,txid_current(),session_user,at_i,generation_i);
 UPDATE private.delayed_children SET state=restored.state,terminal=false,revision=restored.revision,segment=restored.segment,
 available_at=restored.available_at,last_call_at=restored.last_call_at,expires_at=restored.expires_at,started_at=restored.started_at,gameplay_due_at=restored.gameplay_due_at WHERE id=c.id;
 UPDATE private.delayed_matches SET status='active',settled_at=NULL,revision=revision+1 WHERE id=m.id;
 PERFORM private.delayed_notify(m.id);
 RETURN jsonb_build_object('id',p_request,'matchId',m.id,'childId',c.id,'outcome','corrected_unopened','generation',generation_i,'reversalIds',jsonb_build_array(ra->>'id',rb->>'id'),'turnMs',300000,'banks',restored.state->'banks');
END $function$

CREATE OR REPLACE FUNCTION public.delayed_words_action(p_child uuid, p_request uuid, p_revision bigint, p_action text, p_items jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE who uuid:=auth.uid();c private.delayed_children;m private.delayed_matches;prior private.delayed_word_commands;
 fingerprint jsonb:=jsonb_build_object('child',p_child,'revision',p_revision,'action',p_action,'items',p_items);s jsonb;answer jsonb;at_time timestamptz;at_ms bigint;winner uuid;rejection text;
BEGIN
 PERFORM private.delayed_actor(who);
 IF p_request IS NULL THEN RAISE EXCEPTION 'delayed:request_required';END IF;
 PERFORM private.delayed_words_check_health(); PERFORM pg_advisory_xact_lock_shared(731907241);
 PERFORM pg_advisory_xact_lock(hashtextextended(who::text||p_request::text,317));
 SELECT * INTO prior FROM private.delayed_word_commands WHERE actor=who AND request_id=p_request;
 IF FOUND THEN IF prior.fingerprint IS DISTINCT FROM fingerprint THEN RAISE EXCEPTION 'delayed:request_conflict';END IF;RETURN prior.response;END IF;
 SELECT * INTO STRICT m FROM private.delayed_matches WHERE id=(SELECT match_id FROM private.delayed_children WHERE id=p_child) AND who IN(organizer,opponent) FOR UPDATE;
 SELECT * INTO STRICT c FROM private.delayed_children WHERE id=p_child FOR UPDATE;
 IF c.game_type<>'ptown-words' THEN RAISE EXCEPTION 'delayed:scope_closed';END IF;
 at_time:=clock_timestamp();at_ms:=floor(extract(epoch FROM at_time)*1000);
 IF NOT c.terminal AND NOT private.delayed_held(m.id) AND at_time>=coalesce(c.gameplay_due_at,c.expires_at) THEN
  PERFORM private.delayed_expire(c.id,c.segment,c.expires_at);
  answer:=private.delayed_words_view(c.id,who)||jsonb_build_object('error','delayed:deadline');
 ELSIF c.terminal THEN answer:=private.delayed_words_view(c.id,who)||jsonb_build_object('error','delayed:terminal');
 ELSE
  IF m.status<>'active' OR private.delayed_held(m.id) THEN RAISE EXCEPTION 'delayed:on_hold';END IF;
  IF c.actor IS DISTINCT FROM who THEN RAISE EXCEPTION 'delayed:not_your_turn' USING ERRCODE='42501';END IF;
  IF p_revision IS DISTINCT FROM c.revision THEN RAISE EXCEPTION 'delayed:stale_revision';END IF;
  IF p_action IS NULL OR (p_action NOT IN('place','pass','exchange') AND NOT(c.config->>'version' IN ('ptown-words/2','ptown-words/4') AND p_action IN('begin_turn','time_bank'))) OR (p_action='pass' AND p_items IS NOT NULL) THEN RAISE EXCEPTION 'delayed:invalid_action';END IF;
  IF p_action='begin_turn' THEN
   IF p_items IS NOT NULL THEN RAISE EXCEPTION 'delayed:invalid_action'; END IF;
   IF c.gameplay_due_at IS NULL THEN
    IF at_ms<coalesce((c.state#>>'{movePresentation,readyAt}')::bigint,0) THEN RAISE EXCEPTION 'delayed:presenting_move'; END IF;
    s:=jsonb_set(c.state,'{deadline}',to_jsonb(at_ms+(c.config->>'turnMs')::bigint));
    UPDATE private.delayed_children SET state=s,revision=revision+1,started_at=at_time,gameplay_due_at=to_timestamp((s->>'deadline')::bigint/1000.0) WHERE id=c.id;
    UPDATE private.delayed_matches SET revision=revision+1 WHERE id=m.id;
    PERFORM private.delayed_notify(m.id);
   END IF;
   answer:=private.delayed_words_view(c.id,who);
  ELSE
  IF c.config->>'version' IN ('ptown-words/2','ptown-words/4') AND c.gameplay_due_at IS NULL THEN RAISE EXCEPTION 'delayed:enter_turn_first';END IF;
  BEGIN s:=private.ptown_words_reduce(c.state,p_action,p_items,at_ms);
  EXCEPTION WHEN raise_exception THEN GET STACKED DIAGNOSTICS rejection=MESSAGE_TEXT;END;
  IF rejection IS NOT NULL THEN answer:=private.delayed_words_view(c.id,who)||jsonb_build_object('error',rejection);
  ELSE
   IF p_action='time_bank' THEN
    UPDATE private.delayed_children SET state=s,revision=revision+1,gameplay_due_at=to_timestamp((s->>'deadline')::bigint/1000.0) WHERE id=c.id;
    UPDATE private.delayed_matches SET revision=revision+1 WHERE id=m.id;
    PERFORM private.delayed_notify(m.id);
   ELSE PERFORM private.delayed_words_finish_turn(c,s,at_time); END IF;
   answer:=private.delayed_words_view(c.id,who);
  END IF;
  END IF;
 END IF;
 INSERT INTO private.delayed_word_commands VALUES(who,p_request,p_child,fingerprint,answer);
 RETURN answer;
END $function$

CREATE OR REPLACE FUNCTION public.delayed_bonus_choice(p_child uuid, p_actor uuid, p_request uuid, p_revision bigint, p_segment bigint, p_choice text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE r jsonb;s jsonb;fingerprint jsonb;at_ms bigint;committed jsonb;
BEGIN
 IF p_actor IS NULL OR p_request IS NULL OR p_revision IS NULL OR p_segment IS NULL OR p_choice IS NULL OR p_choice NOT IN('play','skip') THEN RAISE EXCEPTION 'bonus:invalid_command';END IF;
 PERFORM pg_advisory_xact_lock_shared(731907241);
 PERFORM pg_advisory_xact_lock(hashtextextended(p_actor::text||p_request::text,319));
 r:=public.delayed_load(p_child,p_actor,p_request);s:=r->'state';at_ms:=(r->>'server_at')::bigint;
 fingerprint:=jsonb_build_object('child',p_child,'revision',p_revision,'segment',p_segment,'intent',jsonb_build_object('type','bonus_'||p_choice));
 IF nullif(r->'receipt','null') IS NOT NULL THEN
  IF r#>>'{receipt,child_id}' IS DISTINCT FROM p_child::text OR r#>'{receipt,fingerprint}' IS DISTINCT FROM fingerprint THEN RAISE EXCEPTION 'delayed:request_conflict';END IF;
  RETURN r;
 END IF;
 IF (r->>'held')::boolean OR (r->>'terminal')::boolean OR r->>'actor' IS DISTINCT FROM p_actor::text
  OR (r->>'revision')::bigint<>p_revision OR (r->>'segment')::bigint<>p_segment THEN RAISE EXCEPTION 'delayed:stale_action';END IF;
 IF at_ms>=floor(extract(epoch FROM (r->>'expires_at')::timestamptz)*1000) THEN RAISE EXCEPTION 'bonus:deadline';END IF;
 IF NOT EXISTS(SELECT FROM private.delayed_matches WHERE id=(r->>'match_id')::uuid AND real_money AND status='active')
  OR s#>>'{optionalBonus,choice}' IS DISTINCT FROM 'pending' OR s#>>'{optionalBonus,actor}' IS DISTINCT FROM p_actor::text
  OR private.optional_bonus_async_actor(r->>'game_type',r->'config',s) IS DISTINCT FROM p_actor::text THEN RAISE EXCEPTION 'bonus:not_eligible' USING ERRCODE='42501';END IF;
 s:=jsonb_set(s,'{optionalBonus,choice}',to_jsonb(p_choice));
 IF p_choice='skip' THEN s:=s||jsonb_build_object('completed',true,'winner',p_actor);END IF;
 -- Existing commit owns immutable outcome, actual finances, notices and archival.
 -- Play preserves segment/availability/deadline. Skip adds no synthetic attempt.
 committed:=public.delayed_commit(p_child,p_actor,p_revision,s,'action',at_ms,p_choice='skip',p_request,fingerprint);
 IF committed->>'outcome' NOT IN('committed','duplicate') THEN RAISE EXCEPTION 'delayed:stale_action';END IF;
 RETURN committed->'record';
END $function$

CREATE OR REPLACE FUNCTION public.delayed_tri_bonus_step(p_child uuid, p_actor uuid, p_request uuid DEFAULT NULL::uuid, p_revision bigint DEFAULT NULL::bigint, p_segment bigint DEFAULT NULL::bigint, p_intent jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v jsonb;decision jsonb;
BEGIN
 v:=public.delayed_tri_step(p_child,p_actor,p_request,p_revision,p_segment,p_intent);
 SELECT state->'optionalBonus' INTO decision FROM private.delayed_children WHERE id=p_child;
 RETURN v||CASE WHEN decision IS NOT NULL AND (decision->>'actor'=p_actor::text OR (v->>'terminal')::boolean) THEN jsonb_build_object('optionalBonus',decision) ELSE '{}'::jsonb END;
END $function$

CREATE OR REPLACE FUNCTION public.delayed_tri_step(p_child uuid, p_actor uuid, p_request uuid DEFAULT NULL::uuid, p_revision bigint DEFAULT NULL::bigint, p_segment bigint DEFAULT NULL::bigint, p_intent jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE r jsonb; next_i jsonb; result_i jsonb; fingerprint jsonb; reviewed jsonb; due_i bigint;
 i integer; stale boolean:=false; action_i text:=p_intent->>'type';
BEGIN
 IF p_actor IS NULL OR p_child IS NULL THEN RAISE EXCEPTION 'delayed:invalid_request';END IF;
 IF p_intent IS NOT NULL AND (p_request IS NULL OR p_revision IS NULL OR p_segment IS NULL OR p_revision<0 OR p_segment<1
  OR action_i IS NULL OR action_i NOT IN('start','remove','draw','take_score')
  OR (action_i='remove' AND (jsonb_typeof(p_intent->'index') IS DISTINCT FROM 'number' OR (p_intent->>'index')::numeric<>trunc((p_intent->>'index')::numeric) OR (p_intent->>'index')::integer NOT BETWEEN 0 AND 27))) THEN RAISE EXCEPTION 'delayed:invalid_command';END IF;
 IF p_intent IS NULL AND (p_request IS NOT NULL OR p_revision IS NOT NULL OR p_segment IS NOT NULL) THEN RAISE EXCEPTION 'delayed:invalid_request';END IF;
 -- Same ordering as commit: global shared lock, request lock, match, child.
 PERFORM pg_advisory_xact_lock_shared(731907241);
 IF p_request IS NOT NULL THEN PERFORM pg_advisory_xact_lock(hashtextextended(p_actor::text||p_request::text,319));END IF;
 r:=public.delayed_load(p_child,p_actor,p_request);
 IF r->>'game_type'<>'tri-towers' THEN RAISE EXCEPTION 'delayed:wrong_game';END IF;
 reviewed:=r->'reviewed';
 fingerprint:=jsonb_build_object('child',p_child,'revision',p_revision,'segment',p_segment,'intent',p_intent);
 IF nullif(r->'receipt','null') IS NOT NULL THEN
  IF r#>>'{receipt,child_id}' IS DISTINCT FROM p_child::text OR r#>'{receipt,fingerprint}' IS DISTINCT FROM fingerprint THEN RAISE EXCEPTION 'delayed:request_conflict';END IF;
  RETURN private.delayed_tri_project(r,p_actor);
 END IF;
 -- Tick recovery is committed even when a subsequently stale action is rejected.
 FOR i IN 1..9 LOOP
  due_i:=least(floor(extract(epoch FROM (r->>'expires_at')::timestamptz)*1000)::bigint,(r#>>'{state,board,deadline}')::bigint);
  EXIT WHEN (r->>'terminal')::boolean OR (r->>'held')::boolean OR due_i>(r->>'server_at')::bigint;
  IF i=9 THEN RAISE EXCEPTION 'delayed:recovery_incomplete';END IF;
  next_i:=private.delayed_tri_transition(r,'{"type":"tick"}');
  result_i:=public.delayed_commit(p_child,p_actor,(r->>'revision')::bigint,next_i->'state','tick',(next_i->>'at')::bigint,(next_i->>'advanced')::boolean);
  r:=(result_i->'record')||jsonb_build_object('reviewed',reviewed);
 END LOOP;
 IF p_intent IS NOT NULL THEN
  IF (r->>'held')::boolean THEN RAISE EXCEPTION 'delayed:held';END IF;
  IF (r->>'terminal')::boolean OR r->>'actor'<>p_actor::text OR (r->>'revision')::bigint<>p_revision OR (r->>'segment')::integer<>p_segment THEN RETURN jsonb_build_object('error','delayed:stale_action');END IF;
  next_i:=private.delayed_tri_transition(r,p_intent);
  result_i:=public.delayed_commit(p_child,p_actor,p_revision,next_i->'state','action',(next_i->>'at')::bigint,(next_i->>'advanced')::boolean,p_request,fingerprint);
  IF result_i->>'outcome' NOT IN('committed','duplicate') THEN
   -- The boundary can expire during SQL execution. Reuse this operation's state
   -- recovery without recording the rejected request or rolling back the tick.
   PERFORM public.delayed_tri_step(p_child,p_actor);
   RETURN jsonb_build_object('error','delayed:stale_action');
  END IF;
  r:=(result_i->'record')||jsonb_build_object('reviewed',reviewed);
 END IF;
 RETURN private.delayed_tri_project(r,p_actor);
END $function$

CREATE OR REPLACE FUNCTION public.delayed_board_core(p_game text, p_operation text, p_config jsonb DEFAULT NULL::jsonb, p_score bigint DEFAULT 0, p_board jsonb DEFAULT NULL::jsonb, p_action text DEFAULT NULL::text, p_items integer[] DEFAULT NULL::integer[], p_at bigint DEFAULT NULL::bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE b jsonb;
BEGIN
 IF p_game='quintzee' THEN
  CASE p_operation
  WHEN 'deal' THEN
   b:=private.quintzee_board_deal(jsonb_build_object('rules',p_config,'score',p_score),p_at);
   -- Begin round is the player's explicit Start; use the unchanged Start reducer.
   RETURN private.quintzee_board_reduce(b,'start',ARRAY[]::integer[],p_at);
  WHEN 'reduce' THEN RETURN private.quintzee_board_reduce(p_board,p_action,p_items,p_at);
  WHEN 'visible' THEN RETURN private.quintzee_present_board(p_board);
  WHEN 'rounds' THEN RETURN to_jsonb(private.quintzee_required_rounds(p_score));
  ELSE RAISE EXCEPTION 'delayed:invalid_core_operation';END CASE;
 ELSIF p_game='boxdrop' THEN
  CASE p_operation
  WHEN 'deal' THEN RETURN private.boxdrop_board_deal(jsonb_build_object('rules',p_config,'score',p_score),p_at);
  WHEN 'reduce' THEN RETURN private.boxdrop_board_reduce(p_board,p_action,p_items,p_at);
  WHEN 'visible' THEN RETURN private.boxdrop_visible(p_board);
  WHEN 'rounds' THEN RETURN to_jsonb(private.boxdrop_required_rounds(p_score));
  ELSE RAISE EXCEPTION 'delayed:invalid_core_operation';END CASE;
 ELSE RAISE EXCEPTION 'delayed:invalid_game';END IF;
END $function$

CREATE OR REPLACE FUNCTION private.delayed_capture_reviews()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE a jsonb; e uuid; o private.delayed_outcomes; move jsonb;
BEGIN
 IF NEW.game_type<>'ptown-words' THEN
  FOR a IN SELECT value FROM jsonb_array_elements(coalesce(NEW.state->'attempts','[]')) LOOP
   e:=NULL;
   INSERT INTO private.delayed_review_events(child_id,match_id,event_key,kind,actor,round,score,completed_at,receipt)
   VALUES(NEW.id,NEW.match_id,NEW.id||':'||(a->>'actor')||':'||(a->>'round'),'attempt',(a->>'actor')::uuid,
    (a->>'round')::int,(a->>'score')::bigint,to_timestamp((a->>'at')::numeric/1000),
    jsonb_build_object('game',NEW.game_type,'rules',NEW.config,'result',a#>'{board,result}'))
   ON CONFLICT(event_key) DO NOTHING RETURNING id INTO e;
   IF e IS NOT NULL THEN INSERT INTO private.delayed_review_boards VALUES(e,private.delayed_review_board(NEW.game_type,a->'board'));END IF;
  END LOOP;
 ELSIF OLD.state->>'turn' IS DISTINCT FROM NEW.state->>'turn' THEN
  move:=NEW.state->'moves'->-1;
  IF move IS NOT NULL THEN
   INSERT INTO private.delayed_review_events(child_id,match_id,event_key,kind,actor,round,score,completed_at,receipt)
   VALUES(NEW.id,NEW.match_id,NEW.id||':word:'||(move->>'turn'),'attempt',(move->>'playerId')::uuid,
    (move->>'turn')::int,(move->>'points')::bigint,clock_timestamp(),jsonb_build_object('game',NEW.game_type,'rules',NEW.config,'move',move))
   ON CONFLICT(event_key) DO NOTHING RETURNING id INTO e;
   IF e IS NOT NULL THEN INSERT INTO private.delayed_review_boards VALUES(e,private.delayed_review_board(NEW.game_type,NEW.state));END IF;
  END IF;
 END IF;
 IF NEW.terminal AND NOT OLD.terminal THEN
  SELECT * INTO STRICT o FROM private.delayed_current_outcomes WHERE child_id=NEW.id;
  INSERT INTO private.delayed_review_events(child_id,match_id,event_key,kind,actor,round,score,completed_at,receipt)
  VALUES(NEW.id,NEW.match_id,NEW.id||':final'||coalesce((SELECT ':'||id::text FROM private.delayed_current_corrections WHERE child_id=NEW.id),''),'child',NULL,0,NULL,o.completed_at,
   jsonb_build_object('game',NEW.game_type,'rules',NEW.config,'reason',o.reason,'winner',o.winner,
    'organizerDelta',o.organizer_delta,'opponentDelta',o.opponent_delta,'stake',NEW.stake))
  ON CONFLICT(event_key) DO NOTHING;
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION private.ptown_words_reduce(s jsonb, action text, items jsonb, at_ms bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
<<reducer>>
DECLARE was_timeout boolean:=action='tick'; board jsonb:=s->'board';old_board jsonb:=board;bag jsonb:=s->'bag';player text:=s->'players'->(s->>'turnIndex')::int->>'id';rack jsonb:=s->'racks'->player;
 used int[]:=ARRAY[]::int[];squares int[]:=ARRAY[]::int[];tile jsonb;item jsonb;cell jsonb;letter text;sq int;i int;j int;k int;r int;c int;dr int;dc int;rr int;cc int;start_r int;start_c int;direction int;seen text[]:=ARRAY[]::text[];key text;word text;words jsonb:='[]';points int:=0;subtotal int;multiplier int;value_i int;premium text;connected boolean:=false;empty_board boolean;rows int[];cols int[];score_before jsonb;deductions jsonb:='{}';deduct int;total_deduct int:=0;person jsonb;went_out boolean:=false;done boolean:=false;count_i int;discard jsonb:='[]';label text;winners jsonb;best int;prebest int;
BEGIN
 IF private.ptown_words_rules_for(s#>>'{rules,version}') IS NULL OR s->'rules' IS DISTINCT FROM private.ptown_words_rules_for(s#>>'{rules,version}') THEN RAISE EXCEPTION 'ptown_words:rules';END IF;
 IF s->>'phase'<>'playing' THEN RAISE EXCEPTION 'ptown_words:phase';END IF;
 IF action='tick' AND s#>>'{rules,version}'='ptown-words/3' THEN RAISE EXCEPTION 'ptown_words:async_expiry_owner';END IF;
 IF action='tick' THEN IF at_ms<(s->>'deadline')::bigint THEN RETURN s;END IF;action:='pass';
 ELSIF at_ms>=(s->>'deadline')::bigint THEN RAISE EXCEPTION 'ptown_words:deadline';END IF;
 IF action<>'tick' AND at_ms<coalesce((s#>>'{movePresentation,readyAt}')::bigint,0) THEN RAISE EXCEPTION 'ptown_words:presenting_move';END IF;

 IF action='time_bank' THEN
  IF s#>>'{rules,version}' NOT IN ('ptown-words/2','ptown-words/4') THEN RAISE EXCEPTION 'ptown_words:time_bank_unavailable';END IF;
  IF jsonb_typeof(items) IS DISTINCT FROM 'array' OR jsonb_array_length(items)<>1 OR jsonb_typeof(items->0->'slot') IS DISTINCT FROM 'number' OR items->0->>'slot' NOT IN ('0','1') THEN RAISE EXCEPTION 'ptown_words:time_bank_slot';END IF;
  i:=(items->0->>'slot')::int;
  IF coalesce(s->'timeBankSpent'->player,'[]'::jsonb) @> jsonb_build_array(i) THEN RAISE EXCEPTION 'ptown_words:time_bank_used';END IF;
  RETURN s||jsonb_build_object('timeBankSpent',coalesce(s->'timeBankSpent','{}'::jsonb)||jsonb_build_object(player,coalesce(s->'timeBankSpent'->player,'[]'::jsonb)||jsonb_build_array(i)),
   'deadline',(s->>'deadline')::bigint+(s#>>'{rules,timeBankMs}')::bigint);
 END IF;
 IF action NOT IN('place','exchange','pass') THEN RAISE EXCEPTION 'ptown_words:invalid_action';END IF;
 IF action IN('place','exchange') THEN
  IF jsonb_typeof(items) IS DISTINCT FROM 'array' OR jsonb_array_length(items) NOT BETWEEN 1 AND 7 THEN RAISE EXCEPTION 'ptown_words:invalid_tiles';END IF;
  FOR item IN SELECT value FROM jsonb_array_elements(items) LOOP
   IF jsonb_typeof(item->'tileId') IS DISTINCT FROM 'number' OR (item->>'tileId') !~ '^[0-9]+$' THEN RAISE EXCEPTION 'ptown_words:tile_id';END IF;
   i:=(item->>'tileId')::int;
   SELECT value INTO tile FROM jsonb_array_elements(rack) WHERE (value->>'id')::int=i;
   IF tile IS NULL OR i=ANY(used) THEN RAISE EXCEPTION 'ptown_words:tile_not_owned';END IF;used:=array_append(used,i);discard:=discard||jsonb_build_array(tile);
   IF action='place' THEN
    IF jsonb_typeof(item->'square') IS DISTINCT FROM 'number' OR (item->>'square') !~ '^[0-9]+$' THEN RAISE EXCEPTION 'ptown_words:square';END IF;
    sq:=(item->>'square')::int;
    IF sq NOT BETWEEN 0 AND 224 OR sq=ANY(squares) OR board->sq IS DISTINCT FROM 'null'::jsonb THEN RAISE EXCEPTION 'ptown_words:occupied_square';END IF;
    letter:=item->>'letter';IF letter IS NULL OR letter !~ '^[A-Z]$' OR (tile->>'face'<>'?' AND letter<>tile->>'face') THEN RAISE EXCEPTION 'ptown_words:blank_letter';END IF;
    squares:=array_append(squares,sq);board:=jsonb_set(board,ARRAY[sq::text],tile||jsonb_build_object('letter',letter,'blank',tile->>'face'='?'));
   END IF;
  END LOOP;
  SELECT coalesce(jsonb_agg(value ORDER BY ordinal),'[]'::jsonb) INTO rack FROM jsonb_array_elements(rack) WITH ORDINALITY t(value,ordinal) WHERE NOT (value->>'id')::int=ANY(used);
 END IF;
 IF action='place' THEN
  SELECT array_agg(DISTINCT x/15),array_agg(DISTINCT x%15) INTO rows,cols FROM unnest(squares)x;
  IF cardinality(rows)>1 AND cardinality(cols)>1 THEN RAISE EXCEPTION 'ptown_words:one_line';END IF;
  empty_board:=NOT EXISTS(SELECT 1 FROM jsonb_array_elements(old_board)v WHERE v<>'null'::jsonb);
  IF empty_board AND NOT 112=ANY(squares) THEN RAISE EXCEPTION 'ptown_words:cover_center';END IF;
  IF cardinality(rows)=1 THEN FOR i IN (SELECT min(x%15) FROM unnest(squares)x)..(SELECT max(x%15) FROM unnest(squares)x) LOOP IF board->(rows[1]*15+i)='null'::jsonb THEN RAISE EXCEPTION 'ptown_words:gap';END IF;END LOOP;
  ELSE FOR i IN (SELECT min(x/15) FROM unnest(squares)x)..(SELECT max(x/15) FROM unnest(squares)x) LOOP IF board->(i*15+cols[1])='null'::jsonb THEN RAISE EXCEPTION 'ptown_words:gap';END IF;END LOOP;END IF;
  FOREACH sq IN ARRAY squares LOOP
   r:=sq/15;c:=sq%15;
   IF (r>0 AND old_board->(sq-15)<>'null'::jsonb) OR (r<14 AND old_board->(sq+15)<>'null'::jsonb) OR (c>0 AND old_board->(sq-1)<>'null'::jsonb) OR (c<14 AND old_board->(sq+1)<>'null'::jsonb) THEN connected:=true;END IF;
   FOR direction IN 0..1 LOOP
    dr:=direction;dc:=1-direction;rr:=r;cc:=c;
    WHILE rr-dr>=0 AND cc-dc>=0 AND board->((rr-dr)*15+cc-dc)<>'null'::jsonb LOOP rr:=rr-dr;cc:=cc-dc;END LOOP;
    start_r:=rr;start_c:=cc;key:=rr||':'||cc||':'||direction;IF key=ANY(seen) THEN CONTINUE;END IF;seen:=array_append(seen,key);
    word:='';subtotal:=0;multiplier:=1;
    WHILE rr<15 AND cc<15 AND board->(rr*15+cc)<>'null'::jsonb LOOP
     k:=rr*15+cc;cell:=board->k;word:=word||(cell->>'letter');value_i:=(cell->>'value')::int;
     IF k=ANY(squares) THEN premium:=private.ptown_words_premium(k);IF premium='DL' THEN value_i:=value_i*2;ELSIF premium='TL' THEN value_i:=value_i*3;ELSIF premium='DW' THEN multiplier:=multiplier*2;ELSIF premium='TW' THEN multiplier:=multiplier*3;END IF;END IF;
     subtotal:=subtotal+value_i;rr:=rr+dr;cc:=cc+dc;
    END LOOP;
    IF length(word)>1 THEN
     IF NOT EXISTS(SELECT 1 FROM private.ptown_words_lexicon l WHERE l.version=s#>>'{rules,dictionaryId}' AND l.word=reducer.word) THEN RAISE EXCEPTION 'ptown_words:invalid_word:%',word;END IF;
     points:=points+subtotal*multiplier;words:=words||jsonb_build_array(jsonb_build_object('word',word,'points',subtotal*multiplier,'square',start_r*15+start_c,'direction',direction));
    END IF;
   END LOOP;
  END LOOP;
  IF (NOT empty_board AND NOT connected) OR jsonb_array_length(words)=0 THEN RAISE EXCEPTION 'ptown_words:disconnected';END IF;
  IF cardinality(squares)=7 THEN points:=points+50;END IF;
  s:=jsonb_set(s,ARRAY['scores',player],to_jsonb((s->'scores'->>player)::int+points));
  s:=s||jsonb_build_object('board',board,'passes',0);label:=(words->0->>'word');
 ELSIF action='exchange' THEN
  IF jsonb_array_length(bag)<7 THEN RAISE EXCEPTION 'ptown_words:need_seven_in_bag';END IF;
  s:=s||jsonb_build_object('passes',0);label:='Exchanged '||cardinality(used)||' tiles';
 ELSE s:=s||jsonb_build_object('passes',(s->>'passes')::int+1);label:='Passed';END IF;
 IF action IN('place','exchange') THEN
  count_i:=least(7-jsonb_array_length(rack),jsonb_array_length(bag));
  FOR i IN 1..count_i LOOP rack:=rack||jsonb_build_array(bag->0);bag:=bag-0;END LOOP;
  IF action='exchange' THEN bag:=private.ptown_words_shuffle(bag||discard);END IF;
 END IF;
 s:=jsonb_set(s,ARRAY['racks',player],rack)||jsonb_build_object('bag',bag);
 went_out:=action='place' AND jsonb_array_length(bag)=0 AND jsonb_array_length(rack)=0;
 done:=went_out OR (s->>'passes')::int>=2*jsonb_array_length(s->'players');
 s:=s||jsonb_build_object('moves',(s->'moves')||jsonb_build_array(jsonb_build_object('turn',(s->>'turn')::int,'playerId',player,'action',action,'words',words,'count',coalesce(cardinality(used),0),'points',points)||CASE WHEN was_timeout THEN jsonb_build_object('reason','timeout') ELSE '{}'::jsonb END),'event',jsonb_build_object('label',label,'points',points),'turn',(s->>'turn')::int+1);
 IF done THEN
  score_before:=s->'scores';
  FOR person IN SELECT value FROM jsonb_array_elements(s->'players') LOOP
   SELECT coalesce(sum((v->>'value')::int),0) INTO deduct FROM jsonb_array_elements(s->'racks'->(person->>'id'))v;
   deductions:=deductions||jsonb_build_object(person->>'id',deduct);total_deduct:=total_deduct+deduct;
   s:=jsonb_set(s,ARRAY['scores',person->>'id'],to_jsonb((s->'scores'->>(person->>'id'))::int-deduct));
  END LOOP;
  IF went_out THEN s:=jsonb_set(s,ARRAY['scores',player],to_jsonb((s->'scores'->>player)::int+total_deduct));END IF;
  SELECT max(value::int) INTO best FROM jsonb_each_text(s->'scores');
  SELECT max((score_before->>x.key)::int) INTO prebest FROM jsonb_each_text(s->'scores')x WHERE x.value::int=best;
  SELECT jsonb_agg(x.key ORDER BY x.key) INTO winners FROM jsonb_each_text(s->'scores')x WHERE x.value::int=best AND (score_before->>x.key)::int=prebest;
  RETURN s||jsonb_build_object('phase','complete','deadline',0,'winnerIds',winners,'preAdjustmentScores',score_before,'rackDeductions',deductions,'endReason',CASE WHEN went_out THEN 'rack_empty' ELSE 'passes' END);
 END IF;
 RETURN s||jsonb_build_object('turnIndex',((s->>'turnIndex')::int+1)%jsonb_array_length(s->'players'),'deadline',at_ms+(s#>>'{rules,turnMs}')::bigint);
END $function$
